use std::fs

fn find(ks: Vec<int>, k: int) -> int {
    let mut i: int = 0
    let n: int = ks.len() as int
    while i < n {
        if ks[i as usize] == k {
            return i
        }
        i += 1
    }
    -1
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut cap: int = 0
    let mut first = true
    let mut ks: Vec<int> = []
    let mut vs: Vec<int> = []
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        if first {
            cap = parts[0].parse::<int>().unwrap_or(1)
            first = false
            continue
        }
        let cmd = parts[0]
        if cmd == "put" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let v = parts[2].parse::<int>().unwrap_or(0)
            let idx = find(ks, k)
            if idx >= 0 {
                ks.remove(idx as usize)
                vs.remove(idx as usize)
            }
            ks.insert(0, k)
            vs.insert(0, v)
            if ks.len() as int > cap {
                let last = ks.len() - 1
                let ek = ks[last]
                ks.remove(last)
                vs.remove(last)
                println("evict ${ek}")
            }
        } else if cmd == "get" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let idx = find(ks, k)
            if idx < 0 {
                println("-1")
            } else {
                let v = vs[idx as usize]
                ks.remove(idx as usize)
                vs.remove(idx as usize)
                ks.insert(0, k)
                vs.insert(0, v)
                println("${v}")
            }
        } else if cmd == "keys" {
            if ks.len() == 0 {
                println("<empty>")
            } else {
                let mut out = ""
                let mut i = 0
                while i < ks.len() {
                    if i > 0 {
                        out = out + " "
                    }
                    out = out + "${ks[i]}"
                    i += 1
                }
                println("${out}")
            }
        }
    }
}

